[{"char_end":571,"char_start":564,"chunk_id":"fdf732938787dcb072dc810f","clause_category":"Parties","document_id":"cuad_aa43b2240f866f2fc18d","score":0.9344,"section_hint":"Parties","text":"Party B"},{"char_end":245,"char_start":238,"chunk_id":"937a944283156187d82aab31","clause_category":"Parties","document_id":"cuad_aa43b2240f866f2fc18d","score":0.8786,"section_hint":"Parties","text":"Party A"},{"char_end":16416,"char_start":16254,"chunk_id":"d5076e24b5f39463d78324d7","clause_category":"Non-Compete","document_id":"cuad_aa43b2240f866f2fc18d","score":0.531,"section_hint":"Non-Compete","text":"Party B shall not advertise, or make any statement favorable for, any competitor having the same or similar business scope as Party A in the services it provides."},{"char_end":70262,"char_start":69816,"chunk_id":"9725587a4df6c532dc5bfc1e","clause_category":null,"document_id":"cuad_aa43b2240f866f2fc18d","score":0.5269,"section_hint":"unlabelled paragraph","text":"8 Party B's working staff shall not, in any name or form whatsoever, provide Party A's working staff with any rebates, money, valuable securities, valuable properties or other articles; nor shall they reimburse any expenses irrelevant to this project for Party A's working staff.

9 Party B shall not invite Party A's working staff to go trips or other luxury entertainment under the name of discussing business or executing economic contracts.

"},{"char_end":69816,"char_start":69197,"chunk_id":"ec584d7d7e5c20e5edf466e6","clause_category":null,"document_id":"cuad_aa43b2240f866f2fc18d","score":0.4911,"section_hint":"unlabelled paragraph","text":"4 Party A's working staff shall not attend any treats or entertainment that may affect Party A's performance of its obligations and duties.

5 Party A's working staff shall not privately discuss this project with Party B or reach a tacit understanding with Party B, nor disclose any bidding internal control information or corporate trade secrets.

6 Party A's working staff shall not seek benefits for his/her family members, relatives or friends in the project by taking advantage of his/her powers or official capacity.

7 Party B shall not privately offer Party A any off-the-book rebates or other money or gifts.

"},{"char_end":57813,"char_start":57257,"chunk_id":"6006aab660699666dd8e86a7","clause_category":null,"document_id":"cuad_aa43b2240f866f2fc18d","score":0.4842,"section_hint":"unlabelled paragraph","text":"  (11) Party B infringes on the communication secrets or personal privacy of users or other persons; (12) Party B delays or fails to fullyperform its obligations and duties hereunder;

  (13) Party B breaches the Undertakings on Network Access Information Safety;

  (14) Party B discretionally uses Party A's name, logo or other relevant information without Party A's consent, which causes adverse impactor economic loss to Party A;

  (15) Party B's illegal advertising or practices has resulted in indemnification or negative media reports of Party A;

"},{"char_end":17717,"char_start":17538,"chunk_id":"2d187923ffd6324a0f03c02b","clause_category":"Anti-Assignment","document_id":"cuad_aa43b2240f866f2fc18d","score":0.4609,"section_hint":"Anti-Assignment","text":"Except otherwise expressly agreed between the parties or agreed by Party A beforehand, Party B shall not transfer any cooperation business to a third party in any form whatsoever."},{"char_end":16254,"char_start":15986,"chunk_id":"4d62c3bd44abb496d75bd7e2","clause_category":null,"document_id":"cuad_aa43b2240f866f2fc18d","score":0.4605,"section_hint":"unlabelled paragraph","text":"3.17 When providing services to users, Party B shall not, in any manner including but not limited to coercion, cajole, fraud or cheat, in order to make users order tailored business and charge fees therefor, or otherwise increase any unnecessary costs to users.

